/* A folded sheet opens over the illustration, never over content or controls. */
.paper-reveal {
  position: relative;
  width: 420px;
  max-width: 100%;
  margin: 28px 0;
  overflow: hidden;
  isolation: isolate;
  background: #fff9ee;
  border: 1px solid #d8cbb5;
}
.paper-reveal img { width: 100%; margin: 0; }
.paper-folds {
  display: none;
  position: absolute;
  inset: 0;
  perspective: 900px;
  pointer-events: none;
}
.paper-reveal.is-opening .paper-folds { display: block; }
.paper-fold {
  position: absolute;
  inset-block: 0;
  width: 50%;
  background: var(--paper);
  backface-visibility: hidden;
  animation: unfold-paper 1400ms cubic-bezier(.22,.65,.3,1) both;
}
.paper-fold--left {
  left: 0;
  --fold-angle: -105deg;
  transform-origin: left center;
  background: linear-gradient(90deg, #ede0c8, var(--paper) 24%, #fff9ee 94%, #ded0b8);
  border-right: 1px solid #c7b89f;
}
.paper-fold--right {
  right: 0;
  --fold-angle: 105deg;
  transform-origin: right center;
  background: linear-gradient(90deg, #e5d7c0, var(--paper) 8%, #fff9ee 76%, #ede0c8);
  animation-delay: 100ms;
}
@keyframes unfold-paper {
  0%, 12% { transform: rotateY(0); opacity: 1; }
  80% { opacity: 1; }
  100% { transform: rotateY(var(--fold-angle)); opacity: 0; }
}
@media (prefers-reduced-motion: reduce) {
  .paper-reveal.is-opening .paper-folds { display: none; }
  .paper-fold { animation: none; }
}
@media print {
  .paper-reveal.is-opening .paper-folds { display: none; }
}
